_choice_available_version() {
    local name="${argc_name:-}"
    [[ -n "$name" ]] || return 0
    _argc_util_cache 3600 _choice_available_version_uncached "asdf-versions-$name"
}

_choice_available_version_uncached() {
    asdf list all "$argc_name" 2>/dev/null
}

_choice_command() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    _argc_util_comp_command
}

_choice_command_args() {
    if [[ "${#argc__positionals[@]}" -lt 2 ]]; then
        _choice_command
    else
        _argc_util_comp_subcommand 0
    fi
}

_choice_installed_version() {
    local name="${argc_name:-}"
    [[ -n "$name" ]] || return 0
    asdf list "$name" 2>/dev/null | gawk '
        { sub(/^[[:space:]]+/, ""); sub(/^\*[[:space:]]*/, "") }
        NF && !/^No / { print $1 }
    '
}

_choice_plugin_add_name() {
    _argc_util_cache 86400 _choice_plugin_add_name_uncached
}

_choice_plugin_add_name_uncached() {
    asdf plugin list all 2>/dev/null | gawk '
        NF > 1 { print $1 "\t" $2 }
        NF == 1 { print $1 }
    '
}

_choice_plugin_name() {
    asdf plugin list 2>/dev/null | gawk 'NF && !/^No plugins installed$/ { print $1 }'
}

_choice_shim() {
    local dir="${ASDF_DATA_DIR:-$HOME/.asdf}/shims" f
    [[ -d "$dir" ]] || return 0
    for f in "$dir"/*; do
        [[ -f "$f" && -x "$f" ]] && printf '%s\n' "${f##*/}"
    done
}
